<?php
class FileService{public static function save($file,$subdir,$allowed,$maxBytes=null){$maxBytes=$maxBytes?:($GLOBALS['app']['upload_max_bytes']??20971520);if(!$file||$file['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Upload failed');if($file['size']>$maxBytes)throw new RuntimeException('File too large');$f=new finfo(FILEINFO_MIME_TYPE);$mime=$f->file($file['tmp_name']);$ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));if(!isset($allowed[$ext])||!in_array($mime,$allowed[$ext],true))throw new RuntimeException('File type not allowed');$name=secure_random(12).'.'.$ext;$dir=__DIR__.'/../uploads/'.$subdir;if(!is_dir($dir))mkdir($dir,0775,true);$dest=$dir.'/'.$name;if(!move_uploaded_file($file['tmp_name'],$dest))throw new RuntimeException('Could not store file');return ['path'=>'uploads/'.$subdir.'/'.$name,'name'=>$name,'mime'=>$mime,'size'=>$file['size']];}}
